namespace sv_85cee4f0d78d4c69928aabeeaee71721.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_85cee4f0d78d4c69928aabeeaee71721.Models;

namespace sv_85cee4f0d78d4c69928aabeeaee71721.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000); // Simulate network call
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(300); // Simulate validation
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@namespace sv_85cee4f0d78d4c69928aabeeaee71721.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => HandleStepClick(stepIndex)">
                <span class="step-badge">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "future";
    }

    private async Task HandleStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnStepClicked.InvokeAsync(index);
        }
    }
}

@namespace sv_85cee4f0d78d4c69928aabeeaee71721.Components.Pages.Apply

<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(e, (v, entry) => entry with { Company = v })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(e, (v, entry) => entry with { Title = v })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => UpdateStartDate(e)" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" disabled="@IsCurrent" @onchange="e => UpdateEndDate(e)" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => ToggleCurrent((bool)e.Value!)" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="e => Update(e, (v, entry) => entry with { Description = v })"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn-danger" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private async Task Update(ChangeEventArgs e, Func<string, WorkEntryModel, WorkEntryModel> updater)
    {
        var updated = updater(e.Value?.ToString() ?? "", Entry);
        await OnChanged.InvokeAsync(updated);
    }

    private async Task UpdateStartDate(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
        {
            await OnChanged.InvokeAsync(Entry with { StartDate = date });
        }
    }

    private async Task UpdateEndDate(ChangeEventArgs e)
    {
        DateTime? date = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null;
        await OnChanged.InvokeAsync(Entry with { EndDate = date });
    }

    private async Task ToggleCurrent(bool isCurrent)
    {
        await OnChanged.InvokeAsync(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }
}

