@namespace sv_85cee4f0d78d4c69928aabeeaee71721.Components.Pages.Apply

<h3>Personal Information</h3>

<div class="form-group">
    <label>Full Name *</label>
    <input type="text" value="@Model.FullName" @onchange="e => Model = Model with { FullName = e.Value?.ToString() ?? "" }" />
</div>

<div class="form-group">
    <label>Email *</label>
    <input type="email" value="@Model.Email" @onchange="e => Model = Model with { Email = e.Value?.ToString() ?? "" }" />
    @if (!string.IsNullOrEmpty(EmailError))
    {
        <span class="validation-error">@EmailError</span>
    }
</div>

<div class="form-group">
    <label>Phone *</label>
    <input type="tel" value="@Model.Phone" @onchange="e => Model = Model with { Phone = e.Value?.ToString() ?? "" }" />
</div>

<div class="form-group">
    <label>Address *</label>
    <textarea rows="2" value="@Model.Address" @onchange="e => Model = Model with { Address = e.Value?.ToString() ?? "" }"></textarea>
</div>

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="validation-error">@ValidationError</div>
}

<div class="step-buttons">
    <button type="button" class="btn-primary" disabled="@IsValidating" @onclick="HandleNext">
        @(IsValidating ? "Validating..." : "Next")
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<PersonalInfoModel> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ValidationError;
    private string? EmailError;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ValidationError = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ValidationError = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();
            var isValid = await ValidateEmail(Model.Email);
            IsValidating = false;

            if (!isValid)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(Model);
    }
}

@namespace sv_85cee4f0d78d4c69928aabeeaee71721.Components.Pages.Apply

<h3>Work History</h3>

