@namespace sv_85cee4f0d78d4c69928aabeeaee71721.Components.Pages.Apply

<h3>Review &amp; Submit</h3>

@if (IsSubmitted)
{
    <div class="confirmation">
        <h4>&#10003; Application Submitted Successfully!</h4>
        <p>Your application ID is: <strong>@ApplicationId</strong></p>
        <p>Thank you for applying. We will be in touch soon.</p>
    </div>
}
else
{
    <section class="review-section">
        <div class="review-header">
            <h4>Personal Information</h4>
            <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
        </div>
        <dl>
            <dt>Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </section>

    <section class="review-section">
        <div class="review-header">
            <h4>Work History</h4>
            <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-item">
                <strong>@entry.Title</strong> at @entry.Company
                <br />
                <small>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</small>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </section>

    <section class="review-section">
        <div class="review-header">
            <h4>References</h4>
            <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="review-item">
                <strong>@r.Name</strong> (@r.Relationship) &mdash; @r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"/ {r.Phone}" : "")
            </div>
        }
    </section>

    <section class="review-section">
        <div class="review-header">
            <h4>Cover Letter</h4>
            <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
        </div>
        <p class="cover-letter-preview">@CoverLetter</p>
    </section>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button type="button" class="btn-primary btn-submit" disabled="@IsSubmitting" @onclick="HandleSubmit">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
}

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = [];
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEdit { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public Func<Task<int>> OnSubmit { get; set; } = default!;

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;
        StateHasChanged();

        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

