    var index = i;
    <ReferenceForm Entry="@Entries[index]"
                   Index="index"
                   CanRemove="@(Entries.Count > 1)"
                   OnChanged="e => UpdateEntry(index, e)"
                   OnRemove="() => RemoveEntry(index)" />
}

@if (Entries.Count < 3)
{
    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Reference</button>
}

