@namespace sv_85cee4f0d78d4c69928aabeeaee71721.Components.Pages.Apply

<h3>References</h3>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <ReferenceForm Entry="@Entries[index]"
                   Index="index"
                   CanRemove="@(Entries.Count > 1)"
                   OnChanged="e => UpdateEntry(index, e)"
                   OnRemove="() => RemoveEntry(index)" />
}

@if (Entries.Count < 3)
{
    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Reference</button>
}

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="validation-error">@ValidationError</div>
}

<div class="step-buttons">
    <button type="button" class="btn-outline" @onclick="HandleBack">Back</button>
    <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> Entries { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void AddEntry()
    {
        if (Entries.Count < 3)
            Entries.Add(new ReferenceModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private void UpdateEntry(int index, ReferenceModel updated)
    {
        Entries[index] = updated;
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        if (Entries.Count < 2)
        {
            ValidationError = "Please provide at least 2 references.";
            return;
        }
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Name) ||
                string.IsNullOrWhiteSpace(entry.Relationship) ||
                string.IsNullOrWhiteSpace(entry.Email))
            {
                ValidationError = "Each reference requires a name, relationship, and email.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();
}

