    border-bottom: 1px solid #f3f4f6;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.review-header h4 {
    margin: 0;
    color: #1f2937;
}

.review-section dl {
    display: grid;
    grid-template-columns: 8rem 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.85rem;
}

.review-section dd {
    margin: 0;
    font-size: 0.9rem;
}

.review-item {
    margin-bottom: 0.75rem;
    padding: 0.5rem;
    background: #f9fafb;
    border-radius: 4px;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9fafb;
    padding: 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation h4 {
    color: #166534;
    font-size: 1.5rem;
}

.confirmation p {
    color: #374151;
    font-size: 1.1rem;
}

