.step-item.completed {
    cursor: pointer;
    color: #166534;
    background: #dcfce7;
}

.step-item.completed:hover {
    background: #bbf7d0;
}

.step-item.active {
    color: #1d4ed8;
    background: #dbeafe;
    font-weight: 600;
}

.step-item.future {
    color: #9ca3af;
    background: #f3f4f6;
