    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 50%;
    font-size: 0.75rem;
    font-weight: 700;
    border: 2px solid currentColor;
}

.checkmark {
    font-size: 0.875rem;
}

