+    <h2>Job Application</h2>
+
+    <StepIndicator CurrentStep="@_currentStep"
+                   StepNames="@_stepNames"
+                   OnStepClicked="GoToStep" />
+
+    <div class="step-content">
+        @switch (_currentStep)
+        {
+            case 0:
+                <PersonalInfoStep Model="@_personalInfo"
+                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
+                                  OnNext="HandlePersonalNext" />
+                break;
+            case 1:
+                <WorkHistoryStep Entries="@_workEntries"
+                                 OnNext="HandleWorkNext"
+                                 OnBack="GoBack" />
+                break;
+            case 2:
+                <ReferencesStep Entries="@_references"
+                                OnNext="HandleReferencesNext"
+                                OnBack="GoBack" />
+                break;
+            case 3:
+                <CoverLetterStep CoverLetter="@_coverLetter"
+                                 OnNext="HandleCoverLetterNext"
+                                 OnBack="GoBack" />
+                break;
+            case 4:
+                <ReviewStep Personal="@_personalInfo"
+                            WorkEntries="@_workEntries"
+                            References="@_references"
+                            CoverLetter="@_coverLetter"
+                            OnEdit="GoToStep"
+                            OnBack="GoBack"
+                            OnSubmit="SubmitApplication" />
+                break;
+        }
+    </div>
+</div>
+
+@code {
+    private static readonly IReadOnlyList<string> _stepNames = new[]
+    {
+        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
+    };
+
+    private int _currentStep;
+    private PersonalInfoModel _personalInfo = new();
+    private List<WorkEntryModel> _workEntries = [new()];
+    private List<ReferenceModel> _references = [new(), new()];
+    private string _coverLetter = "";
+
+    private void GoToStep(int step)
+    {
+        if (step >= 0 && step < _stepNames.Count)
+            _currentStep = step;
+    }
+
+    private void GoBack() => _currentStep = Math.Max(0, _currentStep - 1);
+
+    private void HandlePersonalNext(PersonalInfoModel model)
+    {
+        _personalInfo = model;
+        _currentStep = 1;
+    }
+
+    private void HandleWorkNext(List<WorkEntryModel> entries)
+    {
+        _workEntries = entries;
+        _currentStep = 2;
+    }
+
+    private void HandleReferencesNext(List<ReferenceModel> entries)
+    {
+        _references = entries;
+        _currentStep = 3;
+    }
+
+    private void HandleCoverLetterNext(string coverLetter)
+    {
+        _coverLetter = coverLetter;
+        _currentStep = 4;
+    }
+
+    private async Task<int> SubmitApplication()
+    {
+        var application = new JobApplication(
+            new PersonalInfo(_personalInfo.FullName, _personalInfo.Email, _personalInfo.Phone, _personalInfo.Address),
+            new WorkHistory(_workEntries.Select(e => new WorkEntry(
+                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
+            _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+            _coverLetter
+        );
+        return await ApplicationService.SubmitApplicationAsync(application);
+    }
+}
+

